/bin/zsh -lc "python3 -B - <<'PY'
import hashlib, json
from pathlib import Path
repo=Path.cwd()
r=json.loads((repo/'.intentfold/tickets/STEMROBIN-182/tmp/batch382-7a-n22-position-qualified/affected-review-request.json').read_text())
for group in ('original','current'):
    for name, item in r[group].items():
        if not isinstance(item,dict) or 'path' not in item:
            continue
        raw=Path(item['path']).read_bytes()
        actual=hashlib.sha256(raw).hexdigest()
        assert actual==item['raw_sha256'], (group,name,actual)
        value=json.loads(raw)
        print(group,name,'rawSHA',actual,'top_level_order',list(value))
        if name=='seed':
            print('exercise_order',[e['number'] for e in value['exercises']],'concept_order',[c['block'] for c in value['concepts']],'figures',value['figures'])
        if name=='draft':
            print('question_order',[q['id'] for q in value['questions']],'option_count',sum(len(q['view']['options']) for q in value['questions']),'new_figures',value['new_figures'])
            if group=='current':
                for q in value['questions']:
                    if q['id'] in {b['question_id'] for b in r['option_bindings']}:
                        print(json.dumps({'question_id':q['id'],'source_numbers':q['source_numbers'],'view':q['view']},ensure_ascii=False,indent=2))
PY"

